package com.print.kiosk.controller;
import com.print.kiosk.dto.request.ReopenRequestRequest;import com.print.kiosk.dto.response.RequestActionResponse;import com.print.kiosk.service.interfaces.RequestProcessingService;import jakarta.validation.Valid;import org.springframework.http.ResponseEntity;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/admin/requests") public class AdminRequestProcessingController{private final RequestProcessingService service;public AdminRequestProcessingController(RequestProcessingService s){service=s;}@PostMapping("/{id}/reopen")public ResponseEntity<RequestActionResponse> reopen(@PathVariable Long id,@AuthenticationPrincipal Jwt jwt,@Valid @RequestBody ReopenRequestRequest request){Number n=jwt.getClaim("accountId");if(n==null)throw new IllegalArgumentException("Authenticated account ID is missing");return ResponseEntity.ok(service.reopenByAdmin(id,n.longValue(),request));}}